const usePromptStore = create((set, get) => ({
  request: null,
  prompt: (options) => new Promise((resolve) => {
    const existing = get().request;
    if (existing) existing.resolve(null);
    set({ request: { ...options, resolve } });
  }),
  submit: (value) => {
    const req = get().request;
    if (!req) return;
    req.resolve(value);
    set({ request: null });
  },
  cancel: () => {
    const req = get().request;
    if (!req) return;
    req.resolve(null);
    set({ request: null });
  }
}));

